CREATE TABLE public.audits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  business_name text NOT NULL,
  industry text NOT NULL DEFAULT 'Other',
  team_size integer NOT NULL DEFAULT 1,
  hourly_cost numeric NOT NULL DEFAULT 250,
  workflow_name text NOT NULL,
  description text NOT NULL DEFAULT '',
  runs_per_week numeric NOT NULL DEFAULT 1,
  roles text NOT NULL DEFAULT '',
  tools text NOT NULL DEFAULT '',
  pain_points text NOT NULL DEFAULT '',
  analysis jsonb,
  complexity_costs jsonb NOT NULL DEFAULT '{"low":15000,"medium":40000,"high":90000}'::jsonb,
  status text NOT NULL DEFAULT 'draft',
  is_seed boolean NOT NULL DEFAULT false,
  monthly_hours numeric NOT NULL DEFAULT 0,
  monthly_cost numeric NOT NULL DEFAULT 0,
  hours_saved numeric NOT NULL DEFAULT 0,
  monthly_savings numeric NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.audits TO anon, authenticated;
GRANT ALL ON public.audits TO service_role;
ALTER TABLE public.audits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public can read demo audits" ON public.audits FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.audits (id,business_name,industry,team_size,hourly_cost,workflow_name,description,runs_per_week,roles,tools,pain_points,analysis,complexity_costs,status,is_seed,monthly_hours,monthly_cost,hours_saved,monthly_savings,created_at) VALUES ('11111111-1111-4111-8111-111111111111','Ngiti Dental Clinic (fictional)','Healthcare',12,220,'Patient billing and HMO claims','After each visit the receptionist encodes procedures from paper charts into a spreadsheet, prepares HMO claim forms by hand, follows up claims by phone, and reconciles payments weekly.',60,'Receptionist, Dentist, Billing clerk','Paper charts, Excel, phone, HMO portals','Encoding errors, rejected claims, slow HMO follow-ups, weekly reconciliation takes a full afternoon.','{"steps":[{"name":"Encode procedures from paper chart","owner":"Receptionist","minutes":6,"manual":true,"automatable_share":0.75,"idea":"Use a tablet charting form so procedures are captured once at chairside.","tool_category":"form + database","complexity":"medium"},{"name":"Look up HMO coverage and codes","owner":"Receptionist","minutes":4,"manual":true,"automatable_share":0.5,"idea":"Auto-suggest HMO procedure codes from a maintained coverage table.","tool_category":"form + database","complexity":"low"},{"name":"Fill HMO claim form","owner":"Billing clerk","minutes":8,"manual":true,"automatable_share":0.75,"idea":"Generate pre-filled claim PDFs from the visit record.","tool_category":"document generation","complexity":"medium"},{"name":"Dentist signs claim","owner":"Dentist","minutes":1,"manual":true,"automatable_share":0.5,"idea":"Batch e-signature of daily claims in one click.","tool_category":"e-signature","complexity":"low"},{"name":"Follow up claim status by phone","owner":"Billing clerk","minutes":5,"manual":true,"automatable_share":0.5,"idea":"Track claim status in a dashboard with automated reminder emails to HMOs.","tool_category":"workflow automation","complexity":"medium"},{"name":"Reconcile payments to claims","owner":"Billing clerk","minutes":3,"manual":true,"automatable_share":0.75,"idea":"Use LLM extraction on HMO remittance statements to auto-match payments.","tool_category":"LLM extraction","complexity":"high"}],"risks":["Assumes HMOs accept system-generated claim forms without format changes.","Staff need 1–2 weeks of training to stop using paper charts.","Patient data must comply with the Data Privacy Act of 2012.","Remittance statement formats vary by HMO; extraction accuracy must be reviewed."],"plan":{"d30":{"goal":"Digitize visit capture","tasks":["Build chairside procedure form","Load HMO code table","Train receptionists"]},"d60":{"goal":"Automate claim preparation","tasks":["Generate pre-filled claim PDFs","Add batch e-signature","Launch claim status dashboard"]},"d90":{"goal":"Close the payment loop","tasks":["Extract remittance data with LLM","Auto-match payments to claims","Review accuracy and exceptions weekly"]}}}','{"low":15000,"medium":40000,"high":90000}','analyzed',true,116.91,25720.2,76.86,16908.65,'2026-10-20T09:00:00Z');
INSERT INTO public.audits (id,business_name,industry,team_size,hourly_cost,workflow_name,description,runs_per_week,roles,tools,pain_points,analysis,complexity_costs,status,is_seed,monthly_hours,monthly_cost,hours_saved,monthly_savings,created_at) VALUES ('22222222-2222-4222-8222-222222222222','BiyaheXpress Logistics (fictional)','Logistics',30,260,'Daily dispatch and proof of delivery','The dispatcher receives orders by Viber and email, assigns drivers on a whiteboard, drivers send photos of signed receipts, and an admin encodes PODs and sends an end-of-day status to clients.',40,'Dispatcher, Driver, Admin','Viber, Gmail, whiteboard, Google Sheets','Lost orders in chat, unclear driver assignments, late POD encoding, clients calling for status.','{"steps":[{"name":"Collect orders from Viber and email","owner":"Dispatcher","minutes":10,"manual":true,"automatable_share":0.75,"idea":"Extract order details from chats and emails into a structured order queue.","tool_category":"LLM extraction","complexity":"medium"},{"name":"Assign drivers on whiteboard","owner":"Dispatcher","minutes":8,"manual":true,"automatable_share":0.5,"idea":"Digital dispatch board that suggests drivers by area and load.","tool_category":"form + database","complexity":"medium"},{"name":"Notify drivers of assignments","owner":"Dispatcher","minutes":4,"manual":true,"automatable_share":1,"idea":"Auto-send assignments to drivers via SMS/Viber.","tool_category":"workflow automation","complexity":"low"},{"name":"Drivers send POD photos","owner":"Driver","minutes":3,"manual":true,"automatable_share":0.25,"idea":"Mobile upload form that tags photos to the delivery.","tool_category":"form + database","complexity":"low"},{"name":"Encode POD details","owner":"Admin","minutes":7,"manual":true,"automatable_share":0.75,"idea":"Read receipt photos with LLM extraction to fill POD fields.","tool_category":"LLM extraction","complexity":"high"},{"name":"Send end-of-day status to clients","owner":"Admin","minutes":6,"manual":true,"automatable_share":1,"idea":"Auto-generate and email daily status reports per client.","tool_category":"workflow automation","complexity":"low"}],"risks":["Drivers need reliable mobile data to upload PODs in the field.","Handwritten receipts may reduce extraction accuracy; keep human review.","Clients may want to keep receiving Viber updates instead of email.","Assumes order volume stays near 40 dispatch runs per week."],"plan":{"d30":{"goal":"Single order queue","tasks":["Connect Viber and email intake","Extract orders into a queue","Pilot with two dispatchers"]},"d60":{"goal":"Digital dispatch","tasks":["Launch dispatch board","Auto-notify drivers","Roll out POD upload form"]},"d90":{"goal":"Automated client reporting","tasks":["Extract POD data from photos","Auto-send daily client status","Measure time saved vs baseline"]}}}','{"low":15000,"medium":40000,"high":90000}','analyzed',true,109.69,28520.27,79.38,20639.67,'2026-10-27T09:00:00Z');